{"implementation":"def solve(case):
    def is_int(value):
        return isinstance(value, int) and not isinstance(value, bool)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "segments" not in case or "budget" not in case:
        raise ValueError("missing required field")

    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list) or not is_int(budget):
        raise ValueError("invalid case structure")

    names = []
    importances = []
    minimums = []
    capacities = []
    seen_names = set()

    for segment in segments:
        if not isinstance(segment, dict):
            raise ValueError("segment must be an object")
        for key in ("name", "importance", "minimum", "capacity"):
            if key not in segment:
                raise ValueError("segment missing required field")

        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]

        if not isinstance(name, str):
            raise ValueError("segment name must be a string")
        if name in seen_names:
            raise ValueError("segment names must be unique")
        seen_names.add(name)

        if not (is_int(importance) and is_int(minimum) and is_int(capacity)):
            raise ValueError("numeric segment fields must be integers")
        if minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment quota bounds")

        names.append(name)
        importances.append(importance)
        minimums.append(minimum)
        capacities.append(capacity)

    min_total = sum(minimums)
    cap_total = sum(capacities)
    if budget < min_total or budget > cap_total:
        raise ValueError("infeasible budget")

    allocations = list(minimums)
    remaining = budget - min_total

    while remaining > 0:
        best = None
        best_num = None
        best_den = None

        for index, importance in enumerate(importances):
            if allocations[index] >= capacities[index]:
                continue
            denominator = allocations[index] + 1
            if best is None or importance * best_den > best_num * denominator:
                best = index
                best_num = importance
                best_den = denominator

        if best is None:
            raise ValueError("infeasible budget")

        allocations[best] += 1
        remaining -= 1

    by_name = {names[index]: allocations[index] for index in range(len(names))}
    total = sum(allocations)

    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": total,
    }
